"""sport template v6 (n110): no greyed tabs. Locker Room (storylines from the logs: revenge games, new faces, reunions),
Scheme (how every team plays and what that style gives up to each slot) and DFS (DraftKings-scoring projections) are built
on the sport's own data, like the NFL tabs they mirror. Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'sport_template.html')
s = open(P, encoding='utf-8').read()
if 'function locker()' in s:
    print('already applied'); sys.exit()
def rep(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("{id:'locker',label:'Locker Room',na:'no storylines feed for this league yet'},", "{id:'locker',label:'Locker Room',fn:'locker'},")
rep("{id:'scheme',label:'Scheme',na:'no scheme feed for this league yet'},", "{id:'scheme',label:'Scheme',fn:'scheme'},")
rep("{id:'dfs',label:'DFS',na:'no DFS salary feed for this league yet'},", "{id:'dfs',label:'DFS',fn:'dfs'},")
rep(" splits:{what:'Player splits this season:",
    " locker:{what:'The off-court threads around each game, read from the logs: revenge games (a player facing a team he played for), new faces (changed teams this season) and reunions (former teammates on opposite benches).',how:['each tab is one kind of storyline','vs = his averages against that team in every logged meeting · ▲ ▼ = above / below his season average','click a name for his card']},\n scheme:{what:'How every team plays — pace, shot diet, ball movement, free throws, turnovers — and what that style gives up to each slot.',how:['per-game profile this season with the rank of ' + NT + ' (1 = most) · defense = what the team allows','Ψ per slot = mean rank of what the defense allows across the six stats (1 = softest) · the row\\'s opponent tonight is in the next column','click a team for its defensive profile']},\n dfs:{what:'DraftKings-scoring projections for tonight: points, rebounds, assists, threes, steals, blocks and turnovers folded into DK fantasy points with the double-double bonus, beside his season and last-five DK averages and the matchup.',how:['DK = PTS + 0.5·3PM + 1.25·REB + 1.5·AST + 2·STL + 2·BLK − 0.5·TOV (+1.5 double-double, +3 triple-double)','floor / ceiling from the projection bands · Ψ = mean opponent rank for his slot','no salary feed yet, so value is projection per minute; every column sorts']},\n splits:{what:'Player splits this season:")
rep("/* ---- router ---- */", r"""/* ---- v6: Locker Room · Scheme · DFS ---- */
function teamHist(pid){const by={};(PLOGS[pid]||[]).forEach(l=>{const t=l[LC.team];by[t]=by[t]||{t,n:0,first:l[LC.date],last:l[LC.date]};by[t].n++;if(l[LC.date]<by[t].first)by[t].first=l[LC.date];if(l[LC.date]>by[t].last)by[t].last=l[LC.date]});return Object.values(by).sort((a,b)=>a.last<b.last?1:-1)}
function locker(){const el=$('#players');const tab=G.lk||'revenge';const U=univ();
  const revenge=U.map(p=>{const opp=oppT(p.team);const h=teamHist(p.pid).find(x=>x.t===opp);if(!h)return null;const L=logsOf(p.pid).filter(l=>l[LC.opp]===opp);return {p,opp,h,L}}).filter(Boolean).sort((a,b)=>b.h.n-a.h.n);
  const faces=U.map(p=>{const H=teamHist(p.pid);const prev=H.find(x=>x.t!==p.team&&x.last<(H.find(y=>y.t===p.team)||{first:'9'}).first);return prev?{p,prev}:null}).filter(Boolean).sort((a,b)=>b.prev.n-a.prev.n);
  const reunions=[];GAMESD().forEach(g=>{const A=rotation(g.away).slice(0,J.rotation+2),B=rotation(g.home).slice(0,J.rotation+2);A.forEach(a=>{const ha=teamHist(a.pid);B.forEach(b=>{const hb=teamHist(b.pid);const common=ha.filter(x=>x.t!==g.away&&x.t!==g.home&&hb.some(y=>y.t===x.t&&!(y.last<x.first||x.last<y.first)));if(common.length)reunions.push({a,b,t:common[0].t,g})})})});
  const row=(p,opp,L,extra)=>`<tr><td>${pname(p)}</td><td>${tc(p.team)}</td><td>${slotchip(p.slot)}</td><td>${tc(opp)}</td>${extra}${BST.map(mk=>{const v=mean(L.map(l=>lval(l,mk.k)));const b=p[mk.k];return `<td class="mono" data-v="${v??-1}">${fmt(v,mk.dec)}${v!=null&&b!=null?(v>b+1e-9?'<i class="pa-up">▲</i>':v<b-1e-9?'<i class="pa-dn">▼</i>':''):''}</td>`}).join('')}</tr>`;
  const T={revenge:`<div class="panel wrap-x"><h3>revenge games <span class="f">${revenge.length} players facing a team they played for · games = his logged games in that uniform · then his averages against them since</span></h3><table><thead><tr><th>player</th><th>tm</th><th>slot</th><th>vs</th><th>games there</th><th>last</th><th>meetings</th>${BST.map(mk=>`<th>${mk.label} vs</th>`).join('')}</tr></thead><tbody>${revenge.map(x=>row(x.p,x.opp,x.L,`<td class="mono">${x.h.n}</td><td class="mono mini">${x.h.last}</td><td class="mono">${x.L.length}</td>`)).join('')||'<tr><td colspan="13" class="mini">no revenge games on the slate</td></tr>'}</tbody></table></div>`,
    faces:`<div class="panel wrap-x"><h3>new faces <span class="f">${faces.length} rotation players on a new team this season · from = his last team in the logs · then this season's averages</span></h3><table><thead><tr><th>player</th><th>tm</th><th>slot</th><th>from</th><th>games there</th><th>tonight</th><th>gp</th>${BST.map(mk=>`<th>${mk.label}</th>`).join('')}<th>MIN</th></tr></thead><tbody>${faces.map(x=>`<tr><td>${pname(x.p)}</td><td>${tc(x.p.team)}</td><td>${slotchip(x.p.slot)}</td><td>${tc(x.prev.t)}</td><td class="mono">${x.prev.n}</td><td class="mini">${oppOf(x.p.team)}</td><td class="mono">${x.p.gp}</td>${BST.map(mk=>`<td class="mono">${fmt(x.p[mk.k],mk.dec)} <span class="mini dim">${fmt(x.p[mk.k+'_prior'],mk.dec)}</span></td>`).join('')}<td class="mono">${fmt(x.p.min,0)}</td></tr>`).join('')||'<tr><td colspan="14" class="mini">none</td></tr>'}</tbody></table></div>`,
    reunions:`<div class="panel wrap-x"><h3>reunions <span class="f">${reunions.length} pairs of former teammates on opposite benches tonight</span></h3><table><thead><tr><th>game</th><th>player</th><th>tm</th><th>player</th><th>tm</th><th>together at</th></tr></thead><tbody>${reunions.map(x=>`<tr><td class="mini">${x.g.away} @ ${x.g.home}</td><td>${pname(x.a)}</td><td>${tc(x.a.team)}</td><td>${pname(x.b)}</td><td>${tc(x.b.team)}</td><td>${tc(x.t)}</td></tr>`).join('')||'<tr><td colspan="6" class="mini">none</td></tr>'}</tbody></table></div>`};
  el.innerHTML=`<div class="tabs" id="lkTabs">${[['revenge','revenge games'],['faces','new faces'],['reunions','reunions']].map(([k,l])=>`<button data-k="${k}" class="${tab===k?'on':''}">${l}</button>`).join('')}</div>${T[tab]}`;
  el.querySelectorAll('#lkTabs button').forEach(b=>b.onclick=()=>{G.lk=b.dataset.k;locker()});bindPL(el)}
function scheme(){const el=$('#intel');const KS=[['pts','PTS'],['fga','FGA'],['tpm','3PM'],['fta','FTA'],['ast','AST'],['reb','REB'],['tov','TOV'],['stl','STL'],['blk','BLK']].filter(([k])=>STAT[k]);
  const off={},def={};J.logs.forEach(l=>{if(l[LC.season]!==J.cur)return;const t=l[LC.team],o=l[LC.opp],d=l[LC.date];const a=off[t]=off[t]||{g:new Set()},b=def[o]=def[o]||{g:new Set()};a.g.add(d);b.g.add(d);KS.forEach(([k])=>{a[k]=(a[k]||0)+(+l[LC[k]]||0);b[k]=(b[k]||0)+(+l[LC[k]]||0)})});
  const teams=Object.keys(off).filter(t=>TEAM[t]);const per=(o,k)=>o&&o.g.size?o[k]/o.g.size:null;
  const rk=(obj,k)=>{const v=teams.map(t=>[t,per(obj[t],k)]).filter(x=>x[1]!=null).sort((a,b)=>b[1]-a[1]);const m={};v.forEach((x,i)=>m[x[0]]=i+1);return m};
  const RO={},RD={};KS.forEach(([k])=>{RO[k]=rk(off,k);RD[k]=rk(def,k)});const pace=t=>J.ratings[t]?J.ratings[t].pace:null;const RP=(()=>{const v=teams.map(t=>[t,pace(t)]).filter(x=>x[1]!=null).sort((a,b)=>b[1]-a[1]);const m={};v.forEach((x,i)=>m[x[0]]=i+1);return m})();
  const cell=(v,r,dec)=>v==null?'<td>·</td>':`<td class="op" data-v="${r??99}"><span class="ov">${fmt(v,dec)}</span>${badge(r)}</td>`;
  const rows=teams.filter(inT).map(t=>({t,psi:J.slots.map(sl=>psiOf(t,sl))})).sort((a,b)=>(mean(a.psi.filter(v=>v!=null))??99)-(mean(b.psi.filter(v=>v!=null))??99));
  el.innerHTML=`<div class="controls"><span class="note">${teams.length} teams · per game this season · <b>offense</b> = how the team plays (rank ${NT}: 1 = most) · <b>defense</b> = what it allows · pace = points for + against · <b>Ψ per slot</b> = mean rank of what the defense allows to that slot across PTS REB AST 3PM STL BLK (${G.src}; 1 = softest) · rows ordered by the mean Ψ · every column sorts · click a team for its defensive profile</span></div>
   <div class="panel wrap-x"><table class="lab2"><thead><tr class="grp"><th colspan="3" class="g0">team</th><th colspan="${KS.length}" class="op">offense · per game · rank of ${NT}</th><th colspan="${KS.length}" class="pa">defense · allowed per game · rank of ${NT}</th><th colspan="${J.slots.length}" class="md">Ψ by slot</th></tr><tr><th>team</th><th>next</th><th title="points for + against per game">pace</th>${KS.map(([k,l],i)=>`<th class="op${i===0?' gs':''}">${l}</th>`).join('')}${KS.map(([k,l],i)=>`<th class="pa${i===0?' gs':''}">${l}</th>`).join('')}${J.slots.map(sl=>`<th class="md">${posIcon(sl,11)}</th>`).join('')}</tr></thead><tbody>
   ${rows.map(({t,psi})=>`<tr><td class="plink" data-t="${t}" style="cursor:pointer">${tc(t)}</td><td class="mini">${oppOf(t)}</td><td class="mono" data-v="${pace(t)??-1}">${fmt(pace(t),1)} ${badge(RP[t])}</td>${KS.map(([k,l],i)=>cell(per(off[t],k),RO[k][t],k==='pts'||k==='fga'?1:1)).join('')}${KS.map(([k,l],i)=>`<td class="pa${i===0?' gs':''}" data-v="${RD[k][t]??99}"><span class="ov">${fmt(per(def[t],k),1)}</span>${badge(RD[k][t])}</td>`).join('')}${psi.map(v=>`<td class="md" data-v="${v??99}">${psiCell(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  el.querySelectorAll('td.plink[data-t]').forEach(td=>td.onclick=()=>{const t=td.dataset.t;$('#mbody').innerHTML=`<h3 style="margin:0 0 8px">${tc(t)} defensive profile <span class="f">${G.src} · what it allows per game to each slot with the rank of ${NT} (1 = allows the most)</span></h3><table><thead><tr><th>slot</th>${BST.map(mk=>`<th>${mk.label}</th>`).join('')}<th>Ψ</th></tr></thead><tbody>${J.slots.map(sl=>`<tr><td>${slotchip(sl)}</td>${BST.map(mk=>{const r=rankOf(t,sl,mk.k);return `<td class="op"><span class="ov">${r?fmt(r.avg,mk.dec):'·'}</span>${badge(r?r.rank:null)} <span class="mini dim">lg ${r?fmt(r.lg,mk.dec):'·'}</span></td>`}).join('')}<td>${psiCell(psiOf(t,sl))}</td></tr>`).join('')}</tbody></table>`;$('#modal').classList.add('on')})}
const DKS={pts:1,tpm:.5,reb:1.25,ast:1.5,stl:2,blk:2,tov:-.5};
const dkOf=l=>{let v=0,dd=0;Object.entries(DKS).forEach(([k,w])=>{const x=+l[LC[k]]||0;v+=x*w;if(['pts','reb','ast','stl','blk'].includes(k)&&x>=10)dd++});return v+(dd>=3?4.5:dd>=2?1.5:0)};
function dfs(){const el=$('#picks');const U=univ().filter(posOK).map(p=>{const pj=PJ[p.pid]||{};const opp=oppT(p.team);let proj=0,lo=0,hi=0,ok=false;Object.entries(DKS).forEach(([k,w])=>{const r=pj[k];if(r){ok=true;proj+=r.proj*w;lo+=(w>0?r.q10:r.q90)*w;hi+=(w>0?r.q90:r.q10)*w}else if(p[k]!=null){proj+=p[k]*w;lo+=p[k]*w;hi+=p[k]*w}});
    const L=logsOf(p.pid);const cur=L.filter(l=>l[LC.season]===J.cur);return {p,opp,proj:ok?proj:null,lo,hi,se:mean(cur.map(dkOf)),l5:mean(L.slice(0,5).map(dkOf)),pr:mean(L.filter(l=>l[LC.season]===J.prior).map(dkOf)),psi:psiOf(opp,p.slot),min:his(p,'min')}}).filter(x=>x.proj!=null).sort((a,b)=>b.proj-a.proj);
  el.innerHTML=`${posTabs('bTabs')}<div class="controls">${boardCtl()}<span class="note">${U.length} players · DK = PTS + 0.5·3PM + 1.25·REB + 1.5·AST + 2·STL + 2·BLK − 0.5·TOV, +1.5 for a double-double and +3 for a triple-double · PROJ from tonight's projections (floor / ceiling from their bands) · ${J.cur} and L5 = his actual DK averages from the box scores · Ψ = mean opponent rank for his slot (1 = softest) · DK/min = projection per projected minute (the value column until a salary feed exists)</span></div>
   <div class="panel wrap-x"><table class="lab2"><thead><tr class="grp"><th colspan="6" class="g0">player</th><th colspan="4" class="op">DK projection</th><th colspan="3" class="pa">his DK averages</th><th colspan="2" class="md">matchup</th></tr><tr><th>Player</th><th>Tm</th><th>Slot</th><th>Opp</th><th>Tip</th><th>MIN</th><th class="op gs">PROJ</th><th class="op">floor</th><th class="op">ceil</th><th class="op" title="projection per projected minute">DK/min</th><th class="pa gs">${J.cur}</th><th class="pa">L5</th><th class="pa">${J.prior}</th><th class="md">Ψ</th><th class="md">LINE</th></tr></thead><tbody>
   ${U.map(x=>{const p=x.p;const g=nextGame(p.team);const ln=LINES[p.pid]&&LINES[p.pid].pts;return `<tr><td>${pname(p)}${MISSED().has(p.pid)?' <span class="res L">OUT?</span>':''}</td><td>${tc(p.team)}</td><td>${slotchip(p.slot)}</td><td class="mini">${oppOf(p.team)}</td><td class="mini">${g?fmtT(g.date):''}</td><td class="mono mini">${fmt(x.min,0)}</td><td class="op gs mono" data-v="${x.proj}"><b>${x.proj.toFixed(1)}</b></td><td class="op mono dim">${x.lo.toFixed(0)}</td><td class="op mono dim">${x.hi.toFixed(0)}</td><td class="op mono" data-v="${x.min?x.proj/x.min:-1}">${x.min?(x.proj/x.min).toFixed(2):'·'}</td><td class="pa gs mono" data-v="${x.se??-1}">${fmt(x.se,1)}</td><td class="pa mono" data-v="${x.l5??-1}">${fmt(x.l5,1)}</td><td class="pa mono dim" data-v="${x.pr??-1}">${fmt(x.pr,1)}</td><td class="md" data-v="${x.psi??99}">${psiCell(x.psi)}</td><td class="md" data-v="${ln?ln.edge:-1}">${ln?`<span class="mono">${ln.line}</span> ${lean(ln)}`:'—'}</td></tr>`}).join('')}</tbody></table></div>`;
  bindTabs(el,'bTabs',dfs);bindCtl(el,dfs);bindPL(el)}
/* ---- router ---- */""")
open(P, 'w', encoding='utf-8').write(s)
print('applied')
